/bin/zsh -lc "python -B - <<'PY'
import hashlib, json, pathlib, sqlite3
accounts = {
    'gate': pathlib.Path('paper/cohort_2026-09-28/llm_gate.db'),
    'no_gate': pathlib.Path('paper/cohort_2026-09-28/llm_no_gate.db'),
}

def read_facts(conn):
    tables = {row[0] for row in conn.execute(\"SELECT name FROM sqlite_master WHERE type='table'\")}
    facts = {}
    for table in ('account', 'positions', 'pending_orders', 'trades', 'order_events', 'execution_receipts'):
        if table in tables:
            cur = conn.execute(f'SELECT * FROM {table} ORDER BY rowid')
            cols = [col[0] for col in cur.description]
            facts[table] = [dict(zip(cols, row)) for row in cur]
        else:
            facts[table] = []
    return facts

out = {}
for name, path in accounts.items():
    conn = sqlite3.connect(path.resolve().as_uri() + '?mode=ro', uri=True)
    try:
        conn.execute('BEGIN')
        facts = read_facts(conn)
    finally:
        conn.close()
    facts_hash = hashlib.sha256(json.dumps(facts, sort_keys=True, ensure_ascii=False, allow_nan=False).encode()).hexdigest()
    out[name] = {
        'path': str(path),
        'facts_hash': facts_hash,
        'account_rows': len(facts['account']),
        'positions': len(facts['positions']),
        'pending_orders': len(facts['pending_orders']),
        'trades': len(facts['trades']),
        'order_events': len(facts['order_events']),
        'execution_receipts': len(facts['execution_receipts']),
        'last_account': facts['account'][-1] if facts['account'] else None,
    }
print(json.dumps(out, ensure_ascii=False, sort_keys=True))
PY"
